// Alerta de exemplo, no mesmo formato que o detector.py envia.
// Serve para testar o fluxo pelo botão "Execute workflow", sem rodar o Python.
return [{
  json: {
    body: {
      tipo: 'forca_bruta_ssh',
      host: 'srv-web01',
      ip_origem: '198.51.100.23',
      tentativas_falhas: 7,
      usuarios_alvo: ['financeiro'],
      primeira_tentativa: 'Nov 14 02:14:23',
      ultima_tentativa: 'Nov 14 02:14:41',
      login_com_sucesso_depois: true,
      usuario_que_entrou: 'financeiro',
      amostra_log: [
        'Nov 14 02:14:38 srv-web01 sshd[4126]: Failed password for financeiro from 198.51.100.23 port 38005 ssh2',
        'Nov 14 02:14:41 srv-web01 sshd[4127]: Failed password for financeiro from 198.51.100.23 port 38006 ssh2',
        'Nov 14 02:14:45 srv-web01 sshd[4128]: Accepted password for financeiro from 198.51.100.23 port 38007 ssh2',
      ],
    },
  },
}];

// Os dados chegam de fora (do detector), então conferimos tudo antes de usar.
const a = $json.body ?? {};

const ip = String(a.ip_origem ?? '');
const ipValido = /^(25[0-5]|2[0-4]\d|1?\d?\d)(\.(25[0-5]|2[0-4]\d|1?\d?\d)){3}$/.test(ip);
if (!ipValido) {
  throw new Error('Alerta inválido: ip_origem ausente ou fora do formato IPv4.');
}

const texto = (valor, max) => String(valor ?? '').slice(0, max);
const lista = (valor) => (Array.isArray(valor) ? valor : []);

return {
  json: {
    alerta: {
      tipo: texto(a.tipo || 'desconhecido', 50),
      host: texto(a.host || 'desconhecido', 100),
      ip_origem: ip,
      tentativas_falhas: Number(a.tentativas_falhas) || 0,
      usuarios_alvo: lista(a.usuarios_alvo).slice(0, 20).map((u) => texto(u, 50)),
      primeira_tentativa: texto(a.primeira_tentativa, 30),
      ultima_tentativa: texto(a.ultima_tentativa, 30),
      login_com_sucesso_depois: a.login_com_sucesso_depois === true,
      usuario_que_entrou: a.usuario_que_entrou ? texto(a.usuario_que_entrou, 50) : null,
      // Manda para a IA só um trecho curto do log (economiza tokens e reduz risco)
      amostra_log: lista(a.amostra_log).slice(-5).map((l) => texto(l, 300)),
    },
  },
};

// Lista de bloqueio SIMULADA, só para o projeto.
// Em um SOC de verdade, aqui entraria uma consulta a uma fonte de
// inteligência de ameaças (ex.: AbuseIPDB) ou à lista da empresa.
const listaDeBloqueio = {
  '203.0.113.45': 'visto em campanhas de força bruta SSH',
  '203.0.113.99': 'servidor de comando e controle conhecido',
};

const ip = String(query).trim();
const interno = /^(10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.)/.test(ip);

let resposta = `IP ${ip}: ` + (interno ? 'IP interno da rede. ' : 'IP externo. ');
resposta += listaDeBloqueio[ip]
  ? `ESTÁ na lista de bloqueio (motivo: ${listaDeBloqueio[ip]}).`
  : 'Não está na lista de bloqueio.';
return resposta;

