// Junta o alerta original com a análise da IA.
// A decisão de escalar NÃO fica com a IA: é uma regra fixa, sobre a severidade.
const alerta = $('Validar e padronizar').item.json.alerta;
const ia = $json.output;
const severidade = String(ia.severidade).toLowerCase();

return {
  json: {
    host: alerta.host,
    ip_origem: alerta.ip_origem,
    tipo: alerta.tipo,
    tentativas_falhas: alerta.tentativas_falhas,
    severidade,
    escalar: ['alta', 'critica'].includes(severidade),
    resumo: ia.resumo,
    ip_na_lista_de_bloqueio: ia.ip_na_lista_de_bloqueio,
    tecnica_mitre: ia.tecnica_mitre,
    acoes_recomendadas: ia.acoes_recomendadas,
    analisado_em: new Date().toISOString(),
  },
};

